ompt":"Join the stars in order to find the Backward Bay.","answer":"[\"s0\",\"s1\",\"s2\",\"s3\"]","engine":{"kind":"constellation","name":"Backward Bay","stars":[{"id":"s3","label":"12","x":84,"y":48},{"id":"s2","label":"13","x":62,"y":18},{"id":"s1","label":"14","x":40,"y":18},{"id":"s0","label":"15","x":18,"y":48}],"solution":["s0","s1","s2","s3"]},"hint":"Find the first one, then look for the next each time.","explanation":"Joined in order, the stars draw the Backward Bay."},{"id":"arcade-grade1-stars-10","grade":"grade1","subject":"math","skillId":"MATH.G1.SUB.WITHIN20_01","level":3,"phase":"guided","estimatedMinutes":2,"contextTags":["space","puzzles"],"options":[],"activityType":"constellation","prompt":"Join the stars in order to find the Falling Feather.","answer":"[\"s0\",\"s1\",\"s2\",\"s3\",\"s4\"]","engine":{"kind":"constellation","name":"Falling Feather","stars":[{"id":"s4","label":"2","x":90,"y":24},{"id":"s3","label":"4","x":72,"y":48},{"id":"s2","label":"6","x":52,"y":18},{"id":"s1","label":"8","x":34,"y":48},{"id":"s0","label":"10","x":14,"y":24}],"solution":["s0","s1","s2","s3","s4"]},"hint":"Find the first one, then look for the next each time.","explanation":"Joined in order, the stars draw the Falling Feather."},{"id":"arcade-grade1-stars-11","grade":"grade1","subject":"math","skillId":"MATH.G1.SUB.WITHIN20_01","level":3,"phase":"guided","estimatedMinutes":2,"contextTags":["space","puzzles"],"options":[],"activityType":"constellation","prompt":"Join the stars in order to find the Homeward Trail.","answer":"[\"s0\",\"s1\",\"s2\",\"s3\",\"s4\"]","engine":{"kind":"constellation","name":"Homeward Trail","stars":[{"id":"s4","label":"5","x":88,"y":46},{"id":"s3","label":"10","x":70,"y":24},{"id":"s2","label":"15","x":52,"y":13},{"id":"s1","label":"20","x":34,"y":22},{"id":"s0","label":"25","x":16,"y":46}],"solution":["s0","s1","s2","s3","s4"]},"hint":"Find the first one, then look for the next each time.","explanation":"Joined in order, the stars draw the Homeward Trail."}]'::jsonb) on conflict(name) do update set data=excluded.data,version=catalogs.version+1;
insert into private.catalogs(name,data) values('reading','{"skills":[{"id":"sound_m","letter":"m","phoneme":"/m/","example":"moon","cue":"Close your lips and hum gently. Keep the sound going.","name":"The m sound","domain":"letter-sound","sequence":0,"prerequisites":[]},{"id":"sound_s","letter":"s","phoneme":"/s/","example":"sun","cue":"Let a gentle stream of air hiss between your teeth.","name":"The s sound","domain":"letter-sound","sequence":1,"prerequisites":[]},{"id":"sound_a","letter":"a","phoneme":"/ă/","example":"apple","cue":"Open your mouth for the short a sound at the start of apple.","name":"The a sound","domain":"letter-sound","sequence":2,"prerequisites":[]},{"id":"sound_t","letter":"t","phoneme":"/t/","example":"tap","cue":"Touch your tongue behind your top teeth and release a tiny puff. Do not add “uh”.","name":"The t sound","domain":"letter-sound","sequence":3,"prerequisites":[]},{"id":"sound_p","letter":"p","phoneme":"/p/","example":"pan","cue":"Bring your lips together and release a tiny puff. Do not add “uh”.","name":"The p sound","domain":"letter-sound","sequence":4,"prerequisites":[]},{"id":"sound_i","letter":"i","phoneme":"/ĭ/","example":"in","cue":"Use the short i sound at the start of in, not the letter name.","name":"The i sound","domain":"letter-sound","sequence":5,"prerequisites":[]},{"id":"sound_n","letter":"n","phoneme":"/n/","example":"nap","cue":"Touch your tongue behind your top teeth and let the sound hum through your nose.","name":"The n sound","domain":"letter-sound","sequence":6,"prerequisites":[]},{"id":"blend_vc","name":"Blend two sounds","domain":"decoding","sequence":7,"prerequisites":["sound_a","sound_m"]},{"id":"blend_cvc","name":"Blend three sounds","domain":"decoding","sequence":8,"prerequisites":["sound_m","sound_a","sound_t"]},{"id":"build_cvc","name":"Build a three-sound word","domain":"encoding","sequence":9,"prerequisites":["blend_cvc"]},{"id":"story_detail","name":"Understand a tiny story","domain":"comprehension","sequence":10,"prerequisites":["sound_s","sound_a","sound_m","sound_t","blend_cvc"]}],"words":[{"id":"am","word":"am","graphemes":["a","m"],"phonemes":["/ă/","/m/"],"requiredSkills":["sound_a","sound_m"],"pattern":"VC","meaning":"Being, as in “I am Sam.”","emoji":"💬"},{"id":"at","word":"at","graphemes":["a","t"],"phonemes":["/ă/","/t/"],"requiredSkills":["sound_a","sound_t"],"pattern":"VC","meaning":"A little word that can tell where","emoji":"📍"},{"id":"sam","word":"Sam","graphemes":["s","a","m"],"phonemes":["/s/","/ă/","/m/"],"requiredSkills":["sound_s","sound_a","sound_m"],"pattern":"CVC","meaning":"A person’s name","emoji":"🧒"},{"id":"sat","word":"sat","graphemes":["s","a","t"],"phonemes":["/s/","/ă/","/t/"],"requiredSkills":["sound_s","sound_a","sound_t"],"pattern":"CVC","meaning":"Rested on a seat or the ground","emoji":"🪑"},{"id":"mat","word":"mat","graphemes":["m","a","t"],"phonemes":["/m/","/ă/","/t/"],"requiredSkills":["sound_m","sound_a","sound_t"],"pattern":"CVC","meaning":"A small floor covering","emoji":"🟫"},{"id":"map","word":"map","graphemes":["m","a","p"],"phonemes":["/m/","/ă/","/p/"],"requiredSkills":["sound_m","sound_a","sound_p"],"pattern":"CVC","meaning":"A drawing that shows places","emoji":"🗺️"},{"id":"tap","word":"tap","graphemes":["t","a","p"],"phonemes":["/t/","/ă/","/p/"],"requiredSkills":["sound_t","sound_a","sound_p"],"pattern":"CVC","meaning":"Touch gently","emoji":"👆"},{"id":"pat","word":"pat","graphemes":["p","a","t"],"phonemes":["/p/","/ă/","/t/"],"requiredSkills":["sound_p","sound_a","sound_t"],"pattern":"CVC","meaning":"Touch gently with a flat hand","emoji":"🤚"},{"id":"nap","word":"nap","graphemes":["n","a","p"],"phonemes":["/n/","/ă/","/p/"],"requiredSkills":["sound_n","sound_a","sound_p"],"pattern":"CVC","meaning":"A short sleep","emoji":"💤"},{"id":"pan","word":"pan","graphemes":["p","a","n"],"phonemes":["/p/","/ă/","/n/"],"requiredSkills":["sound_p","sound_a","sound_n"],"pattern":"CVC","meaning":"A container for cooking","emoji":"🍳"},{"id":"pin","word":"pin","graphemes":["p","i","n"],"phonemes":["/p/","/ĭ/","/n/"],"requiredSkills":["sound_p","sound_i","sound_n"],"pattern":"CVC","meaning":"A small fastener; ask a grown-up to handle it","emoji":"📌"},{"id":"sit","word":"sit","graphemes":["s","i","t"],"phonemes":["/s/","/ĭ/","/t/"],"requiredSkills":["sound_s","sound_i","sound_t"],"pattern":"CVC","meaning":"Rest on a seat or the ground","emoji":"🪑"},{"id":"sip","word":"sip","graphemes":["s","i","p"],"phonemes":["/s/","/ĭ/","/p/"],"requiredSkills":["sound_s","sound_i","sound_p"],"pattern":"CVC","meaning":"Take a small drink","emoji":"🥤"},{"id":"tip","word":"tip","graphemes":["t","i","p"],"phonemes":["/t/","/ĭ/","/p/"],"requiredSkills":["sound_t","sound_i","sound_p"],"pattern":"CVC","meaning":"The end of something","emoji":"✏️"},{"id":"tin","word":"tin","graphemes":["t","i","n"],"phonemes":["/t/","/ĭ/","/n/"],"requiredSkills":["sound_t","sound_i","sound_n"],"pattern":"CVC","meaning":"A kind of metal or a small metal container","emoji":"🥫"},{"id":"man","word":"man","graphemes":["m","a","n"],"phonemes":["/m/","/ă/","/n/"],"requiredSkills":["sound_m","sound_a","sound_n"],"pattern":"CVC","meaning":"An adult person","emoji":"🧑"},{"id":"tan","word":"tan","graphemes":["t","a","n"],"phonemes":["/t/","/ă/","/n/"],"requiredSkills":["sound_t","sound_a","sound_n"],"pattern":"CVC","meaning":"A light brown color","emoji":"🟤"},{"id":"ant","word":"ant","graphemes":["a","n","t"],"phonemes":["/ă/","/n/","/t/"],"requiredSkills":["sound_a","sound_n","sound_t"],"pattern":"VCC","meaning":"A tiny six-legged insect","emoji":"🐜"}],"settings":{"sequence":["m","s","a","t","p","i","n"],"readyScore":0.3,"masteredScore":0.85,"reviewDays":[1,3,7,14,30]},"stories":[{"id":"sam-sat","title":"Sam Sat","requiredSkills":["sound_s","sound_a","sound_m","sound_t","blend_cvc"],"pages":["Sam!","Sam sat."],"question":"What did Sam do?","choices":["sat","ran"],"answer":"sat","emoji":"🧒"}]}'::jsonb) on conflict(name) do update set data=excluded.data,version=catalogs.version+1;
insert into private.catalogs(name,data) values('experience','{"media":[{"id":"missing-map","title":"Nova and the Missing Map","category":"CurioQuest Cartoons","domain":"reading","skills":["sound_m","sound_a","sound_p","blend_cvc"],"ageMin":3,"ageMax":8,"duration":240,"active":true,"videoUrl":null,"captionUrl":null,"thumbnail":"map","scenes":[{"id":"forest","caption":"A treasure garden is waiting! Nova packed a snack and a compass. But where is the map?","setting":"forest","duration":7,"nova":"wave"},{"id":"glow","caption":"A little light flickers near a tree. The first sound in moon will help us find its letter.","setting":"letters","duration":7,"nova":"point","letters":"m"},{"id":"sounds","caption":"Three letters are glowing. Touch m, then a, then p. Say each sound with your grown-up.","setting":"letters","duration":7,"nova":"listen","letters":"m a p"},{"id":"bridge","caption":"Bring the sounds together. Keep the first two sounds going, then finish with a tiny p.","setting":"letters","duration":7,"nova":"explain","letters":"m a p"},{"id":"word","caption":"The sounds make a word! Read it first. Then we can discover what it means.","setting":"letters","duration":6,"nova":"encourage","letters":"map"},{"id":"route","caption":"A map shows a route. Which word did we read? Look at every letter.","setting":"forest","duration":7,"nova":"listen"},{"id":"garden","caption":"You helped Nova reach the treasure garden! Your Explorer Map belongs in your treehouse.","setting":"garden","duration":7,"nova":"celebrate"}]},{"id":"sleeping-moon","title":"The Sleeping Moon","category":"CurioQuest Cartoons","domain":"science","skills":[],"ageMin":3,"ageMax":8,"duration":180,"active":false,"videoUrl":null,"captionUrl":null,"thumbnail":"moon","scenes":[]},{"id":"balance-bridge","title":"The Bridge That Wouldn’t Balance","category":"CurioQuest Cartoons","domain":"math","skills":[],"ageMin":3,"ageMax":8,"duration":180,"active":false,"videoUrl":null,"captionUrl":null,"thumbnail":"bridge","scenes":[]},{"id":"creature-mystery","title":"Creature Grove Mystery","category":"CurioQuest Cartoons","domain":"science","skills":[],"ageMin":3,"ageMax":8,"duration":180,"active":false,"videoUrl":null,"captionUrl":null,"thumbnail":"creature","scenes":[]},{"id":"rhythm-robot","title":"The Rhythm Robot","category":"CurioQuest Cartoons","domain":"logic","skills":[],"ageMin":3,"ageMax":8,"duration":180,"active":false,"videoUrl":null,"captionUrl":null,"thumbnail":"robot","scenes":[]}],"cues":[{"id":"find-m","mediaId":"missing-map","scene":1,"at":5,"kind":"choice","prompt":"Which letter starts the sound in moon?","choices":["s","m","a","p"],"answer":"m","skillId":"sound_m","help":"Close your lips and hum. The letter is m."},{"id":"tap-map","mediaId":"missing-map","scene":2,"at":5,"kind":"sequence","prompt":"Touch the sounds from left to right: m, a, p.","choices":["p","m","a"],"answer":"map","skillId":"blend_cvc","help":"First m, next a, then p. This is guided sound practice."},{"id":"blend-map","mediaId":"missing-map","scene":3,"at":5,"kind":"blend","prompt":"Slide the sounds together. What word do they make?","choices":["mat","map","pat","tap"],"answer":"map","skillId":"blend_cvc","help":"Stretch m and short a, then finish with p. The word is map."},{"id":"read-map","mediaId":"missing-map","scene":5,"at":5,"kind":"choice","prompt":"Which word did the sounds make?","choices":["tap","pat","map","mat"],"answer":"map","skillId":"blend_cvc","help":"Look at all three letters: m, a, p. Map."}],"items":[{"id":"explorer-map","name":"Explorer Map","art":"map","category":"decorations","zone":"treehouse","unlock":"Finish Nova and the Missing Map","description":"A reminder that sounds can open a new path."},{"id":"moon-lamp","name":"Moon Lamp","art":"moon","category":"science objects","zone":"treehouse","unlock":"Finish Today’s Adventure","description":"A gentle glow for your cozy reading corner."},{"id":"creature-poster","name":"Creature Poster","art":"creature","category":"decorations","zone":"treehouse","unlock":"Reserved for a future habitat episode","description":"Room for discoveries about living things."},{"id":"robot-toy","name":"Robot Toy","art":"robot","category":"toys","zone":"treehouse","unlock":"Finish a Space Collector mission","description":"A friendly rover who loves a careful thinker."},{"id":"bridge-blueprint","name":"Bridge Blueprint","art":"bridge","category":"machines","zone":"treehouse","unlock":"Reserved for a future bridge episode","description":"An idea for something you could build together."},{"id":"nova-storybook","name":"Nova Storybook","art":"book","category":"books","zone":"treehouse","unlock":"Finish the tiny story in Today’s Adventure","description":"Small words tell a whole story."},{"id":"discovery-plant","name":"Discovery Plant","art":"plant","category":"plants","zone":"treehouse","unlock":"A grown-up confirms your real-world mission","description":"Curiosity grows beyond the screen."},{"id":"star-globe","name":"Star Globe","art":"globe","category":"science objects","zone":"treehouse","unlock":"Finish Today’s Adventure","description":"A world of questions, ready to explore."}]}'::jsonb) on conflict(name) do update set data=excluded.data,version=catalogs.version+1;
insert into private.catalogs(name,data) values('stories','{"stories":[{"id":"waiting-turn","title":"The swing worth waiting for","category":"character","emoji":"🌳","lesson":"Patience is easier with a plan, a calm breath, and fair turns.","scenes":[{"title":"One swing, two friends","text":"Tiko reaches the swing just as Mira sits down. Tiko really wants a turn. His feet feel jumpy.","emoji":"🌳","prompt":"What could Tiko do?","choices":[{"label":"Ask when it will be my turn","response":"Mira and Tiko agree to take turns after a short song."},{"label":"Push the swing away","response":"Pushing could hurt someone. Tiko can step back and use words."}]},{"title":"A waiting plan","text":"Tiko watches a bird while he waits. He slowly breathes in and out. Waiting still feels difficult, but he has something gentle to do.","emoji":"🐦","prompt":"What might help you wait?","choices":[{"label":"Notice three sounds","response":"Listening gives your attention a small, calm job."},{"label":"Ask a grown-up to help","response":"A grown-up can help everyone agree on fair turns."}]},{"title":"Room for everyone","text":"When the song ends, Mira gives Tiko a turn. Later, Tiko remembers to offer the swing back. Fairness needs everyone’s help.","emoji":"🤝","prompt":"What is a fair way to share a favorite toy?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"lost-tool","title":"Byte’s missing spade","category":"character","emoji":"🪴","lesson":"Responsibility means caring for shared things and repairing mistakes.","scenes":[{"title":"Time to plant","text":"Byte cannot find the little spade. Pip remembers leaving it beside the path yesterday.","emoji":"🪴","prompt":"What could Pip say?","choices":[{"label":"I used it. I will help look.","response":"Pip tells the truth and helps solve the problem."},{"label":"Someone else must have lost it","response":"Blaming without knowing does not help. Pip can explain what he remembers."}]},{"title":"Found in the grass","text":"The friends find the spade. It needs cleaning. Byte feels relieved, and Pip wants to make a better plan.","emoji":"🧰","prompt":"Where should the spade go?","choices":[{"label":"A labeled tool basket","response":"A clear home makes it easier for everyone to find it."},{"label":"A different place each time","response":"A changing hiding place would make finding it harder."}]},{"title":"A small new habit","text":"Pip draws a picture label for the basket. After planting, the friends clean and return their tools together.","emoji":"🌱","prompt":"What is one shared thing you can help care for?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"thank-you-map","title":"Mira’s thank-you map","category":"character","emoji":"💌","lesson":"Gratitude means noticing care and finding your own way to respond.","scenes":[{"title":"A busy morning","text":"Someone prepared breakfast. Someone found Mira’s lost shoe. Mira notices that little acts of care helped her day begin.","emoji":"🏡","prompt":"How could Mira remember them?","choices":[{"label":"Draw a thank-you map","response":"She draws the people and the helpful things they did."},{"label":"Tell them what I noticed","response":"A specific thank-you helps someone know their care mattered."}]},{"title":"A gift without a shop","text":"Mira wants to give something back. She has paper, crayons, and a little time.","emoji":"🖍️","prompt":"What could she offer?","choices":[{"label":"A picture and a kind note","response":"A thoughtful homemade gift can mean a lot."},{"label":"Help with a safe family job","response":"Sharing time and effort is another way to show care."}]},{"title":"No perfect words needed","text":"Mira shares her picture. Her thank-you does not need to sound fancy. It is enough to notice and express care sincerely.","emoji":"💛","prompt":"Name one small thing you appreciated today.","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"kind-boundaries","title":"A kind and clear no","category":"character","emoji":"🫶","lesson":"Kindness includes respecting feelings, personal space, and safe boundaries.","scenes":[{"title":"A hug or a wave?","text":"Nova wants to welcome a friend with a hug. The friend steps back and says, “I would like a wave today.”","emoji":"👋","prompt":"What could Nova do?","choices":[{"label":"Wave and smile","response":"Nova respects the choice. Friends can welcome each other in different ways."},{"label":"Hug anyway","response":"The friend has said no. Caring means listening to that boundary."}]},{"title":"An uncomfortable game","text":"Later, a game feels too rough for Mira. She wants to stop, even though the others are still playing.","emoji":"🛑","prompt":"What can Mira say?","choices":[{"label":"Please stop. I need space.","response":"Clear words help others understand. She can move away and find a trusted grown-up."},{"label":"I have to keep playing","response":"Mira is allowed to stop. Her comfort and safety matter."}]},{"title":"Safe people listen","text":"The friends slow down and choose a gentler game. If someone does not listen, a trusted grown-up can help.","emoji":"🤝","prompt":"Who can help when you need to say no or ask for space?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"abraham","title":"A journey of trust","category":"faith","emoji":"✨","reference":"Genesis 12; 15","lesson":"We can take a new step while caring for the people around us.","scenes":[{"title":"A new beginning","text":"God called Abraham to leave his familiar home and begin a journey. Abraham did not know every part of the path ahead.","emoji":"🛤️","prompt":"How does it feel to go somewhere new?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"Under the stars","text":"God told Abraham to look at the stars as he spoke about a promise for the future. Imagine that enormous, sparkling sky.","emoji":"✨","prompt":"How could you make a star picture?","choices":[{"label":"Draw groups of five","response":"Grouping can help you count your stars."},{"label":"Make different patterns","response":"Your sky can have bright patterns of its own."}]},{"title":"A step at a time","text":"Abraham’s family continued their journey. New beginnings can call for trust, patience, and help from others.","emoji":"⛺","prompt":"Who helps you when you begin something new?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"joseph","title":"Joseph and a second chance","category":"faith","emoji":"🌾","reference":"Genesis 37; 41–45","lesson":"Planning and forgiveness can help people care for one another.","scenes":[{"title":"A difficult beginning","text":"Joseph’s brothers treated him unkindly, and he was taken far from home. His story had many difficult days. Hurting someone is never a good way to handle jealousy.","emoji":"💜","prompt":"What can you do when you feel jealous?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"Planning ahead","text":"Years later, Joseph helped people in Egypt store grain during years when much food grew. The stored food helped during years when little grew.","emoji":"🌾","prompt":"Why store some food?","choices":[{"label":"To be ready for a time with less","response":"Planning ahead can help us care for people later."},{"label":"To keep every bit for ourselves","response":"Joseph’s plan helped many people get food, not only himself."}]},{"title":"Meeting again","text":"When Joseph met his brothers again, he chose to help his family. Families can talk about forgiveness, making amends, and getting help to stay safe.","emoji":"🤝","prompt":"How can someone begin to make an unkind choice right?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"moses","title":"Moses and a path to freedom","category":"faith","emoji":"🌊","reference":"Exodus 3; 14–16","lesson":"Leadership includes asking for help and caring for others.","scenes":[{"title":"An important call","text":"God called Moses to help lead the Israelites out of slavery. Moses wondered whether he could do such a difficult job. He would not have to face it alone.","emoji":"🔥","prompt":"Who can you ask for help with a difficult job?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"A way through","text":"At the sea, the people were afraid. The Bible tells how God made a path through the water, and Moses led the people across.","emoji":"🌊","prompt":"What helps a group move safely together?","choices":[{"label":"Listen and help each other","response":"A group needs care, patience, and attention."},{"label":"Race ahead alone","response":"Staying with trusted helpers is safer than racing away."}]},{"title":"Learning together","text":"The journey continued. The people needed food, rest, and ways to live together. Learning to care for a community takes practice.","emoji":"⛺","prompt":"What is one helpful job you can do in your family?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"daniel","title":"Daniel’s steady courage","category":"faith","emoji":"🦁","reference":"Daniel 6","lesson":"Courage and faith can help us face hard moments.","scenes":[{"title":"A daily habit","text":"Daniel prayed regularly. Prayer was an important part of his life, even when other people made things difficult for him.","emoji":"🪟","prompt":"What is a caring habit you practice each day?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"A frightening night","text":"Daniel was put in a den of lions. The Bible tells that God sent an angel to keep him safe. This is a story of faith, not an invitation to approach wild animals.","emoji":"🦁","prompt":"What should we do near a wild animal?","choices":[{"label":"Keep a safe distance with a grown-up","response":"We can admire animals while giving them space."},{"label":"Try to pet it","response":"Wild animals need space. Stay with a trusted grown-up."}]},{"title":"A thankful morning","text":"Daniel came out safely. The king was glad, and Daniel’s faith was remembered. We can talk with our family about courage and trust.","emoji":"☀️","prompt":"What helps you feel supported when you are afraid?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"jonah","title":"Jonah tries again","category":"faith","emoji":"🐟","reference":"Jonah 1–4","lesson":"We can change direction and show compassion.","scenes":[{"title":"The other direction","text":"God asked Jonah to bring a message to Nineveh. Jonah did not want to go. He got on a boat going another way.","emoji":"⛵","prompt":"Have you ever wanted to avoid a difficult job?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"A chance to think","text":"After a storm, Jonah was swallowed by a great fish. Inside, he prayed. The Bible tells that the fish brought him back to dry land.","emoji":"🐟","prompt":"What can help us after a mistake?","choices":[{"label":"Pause and ask for help","response":"We can think about what happened and choose a new step."},{"label":"Pretend nothing happened","response":"Noticing a mistake is the beginning of making a change."}]},{"title":"Compassion for others","text":"Jonah went to Nineveh. The people changed their ways, and God showed mercy. Jonah still had things to learn about caring for others.","emoji":"🏘️","prompt":"How can you give someone room to try again?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"creation","title":"A world to care for","category":"faith","emoji":"🌍","reference":"Genesis 1–2","lesson":"We can notice and care for the world around us.","prayer":"Dear God, thank you for our wonderful world. Help us care for living things. Amen.","scenes":[{"title":"Light and sky","text":"The Bible begins with God making a world of light, sky, land, and water. Imagine seeing a sunrise for the very first time.","emoji":"☀️","prompt":"What would you notice?","choices":[{"label":"The light","response":"Light helps us see colors and shapes."},{"label":"The water","response":"Water is part of the home living things share."}]},{"title":"A living world","text":"Plants grew, creatures filled the sea and sky, and animals lived on the land. There were so many different living things.","emoji":"🌳","prompt":"Which creatures could you draw together?","choices":[{"label":"Birds and fish","response":"Birds and fish live in different places. How would you show that?"},{"label":"Trees and butterflies","response":"A garden can give little creatures food and shelter."}]},{"title":"People and rest","text":"God made people and called creation good. The story also makes room for rest. Caring, creating, and resting can all be part of our day.","emoji":"🌿","prompt":"How could you care for one living thing today?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"noah","title":"Noah and the rainbow","category":"faith","emoji":"🌈","reference":"Genesis 6–9","lesson":"Care takes patience and responsibility.","prayer":"Dear God, help us care for others and remember hope. Amen.","scenes":[{"title":"A very big boat","text":"God asked Noah to build an ark. Noah had a big job to do, one piece at a time.","emoji":"⛵","prompt":"What helps with a big job?","choices":[{"label":"Plan small steps","response":"A plan helps us know what to try first."},{"label":"Ask for help","response":"Working together can make a big job easier."}]},{"title":"Animals aboard","text":"Animals came aboard the ark. Noah and his family cared for them while rain fell. Imagine the sounds inside that busy boat.","emoji":"🦁","prompt":"Two birds and two rabbits: how many animals?","choices":[{"label":"Four","response":"Two and two make four."},{"label":"Three","response":"Count each pair: one, two, three, four."}]},{"title":"A rainbow of hope","text":"When the water went down, the family and animals could leave the ark. A rainbow became a sign of God’s promise.","emoji":"🌈","prompt":"What colors would you put in a picture of hope?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"david","title":"David takes a brave step","category":"faith","emoji":"🪨","reference":"1 Samuel 17","lesson":"Courage can mean doing a difficult thing with care and help.","scenes":[{"title":"A young helper","text":"David was a young shepherd. He practiced caring for his sheep and learned to face difficult moments.","emoji":"🐑","prompt":"What is something you practiced before it felt easier?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"Five smooth stones","text":"David chose five smooth stones from a stream before facing the giant Goliath. He trusted God and used what he had learned.","emoji":"🪨","prompt":"How could you show five stones?","choices":[{"label":"Count one at a time","response":"Touch five imaginary stones as you count."},{"label":"Make a group of two and three","response":"Two and three make five."}]},{"title":"Courage and peace","text":"David’s brave action helped his people. We can practice everyday courage by telling the truth, asking for help, and standing beside someone who feels alone.","emoji":"💛","prompt":"What is a kind, brave thing you could do?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"nativity","title":"A baby in Bethlehem","category":"faith","emoji":"⭐","reference":"Luke 2; Matthew 2","lesson":"Small beginnings can be full of love.","prayer":"Dear God, thank you for Jesus and for love in our family. Amen.","scenes":[{"title":"A long journey","text":"Mary and Joseph traveled to Bethlehem. They needed a place to rest. Soon, baby Jesus was born.","emoji":"🏘️","prompt":"What helps a tired traveler feel welcome?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"A quiet welcome","text":"Mary wrapped the baby snugly and laid him in a manger. Shepherds heard wonderful news and came to see him.","emoji":"🐑","prompt":"What could we bring to a family with a new baby?","choices":[{"label":"A helpful hand","response":"Helping with a small job can be a loving gift."},{"label":"A gentle welcome","response":"A quiet voice can help a resting baby."}]},{"title":"Sharing joy","text":"The shepherds shared what they had heard and seen. Later, wise visitors also came with gifts. Christians remember this story at Christmas.","emoji":"⭐","prompt":"How can you share joy without buying anything?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"children","title":"Jesus welcomes the children","category":"faith","emoji":"💛","reference":"Mark 10:13–16","lesson":"Children matter and deserve kindness and welcome.","scenes":[{"title":"Children arrive","text":"Families brought their children to Jesus. They hoped the children could be close to him and receive his blessing.","emoji":"👪","prompt":"How does it feel when someone welcomes you?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"Make room","text":"Some grown-ups tried to send the children away. Jesus told them to let the children come. There was room for them.","emoji":"🤲","prompt":"How could we make room for someone new?","choices":[{"label":"Invite them to join","response":"An invitation can help someone feel they belong."},{"label":"Listen to their idea","response":"Listening tells someone their thoughts matter."}]},{"title":"A blessing","text":"Jesus welcomed the children and blessed them. Every child in our community deserves care.","emoji":"🌼","prompt":"Who could you welcome today?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"samaritan","title":"The neighbor who stopped","category":"faith","emoji":"🤝","reference":"Luke 10:25–37","lesson":"Kindness can cross differences.","scenes":[{"title":"Someone needs help","text":"Jesus told a story about a traveler who was hurt beside a road. Some people passed without helping.","emoji":"🛤️","prompt":"What should a child do if someone is hurt? Tell a trusted grown-up.","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"A neighbor stops","text":"A Samaritan stopped, cared for the traveler, and helped him reach a safe place to rest.","emoji":"🫶","prompt":"Which action showed care?","choices":[{"label":"Stopping to help","response":"He noticed someone’s need and acted kindly."},{"label":"Looking away","response":"Looking away would leave the traveler without help. We can ask a trusted grown-up to help."}]},{"title":"Be a neighbor","text":"Jesus used this story to teach about loving our neighbors. A neighbor can be someone whose life is different from ours.","emoji":"🏡","prompt":"What small act of kindness could you do today?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"sheep","title":"One sheep matters","category":"faith","emoji":"🐑","reference":"Luke 15:3–7","lesson":"Each person matters.","scenes":[{"title":"A missing sheep","text":"Jesus told a story about a shepherd who noticed that one sheep was missing. The shepherd cared about that one sheep.","emoji":"🐑","prompt":"How can we notice when someone is left out?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"Looking carefully","text":"The shepherd searched until he found the sheep. He was so glad to bring it home.","emoji":"🔎","prompt":"A friend is alone at playtime. What could you do?","choices":[{"label":"Invite them to play","response":"An invitation can help them feel included."},{"label":"Ask what they enjoy","response":"You might discover a new game together."}]},{"title":"Joy together","text":"The shepherd celebrated finding the sheep. Jesus’ story reminds Christians of God’s care.","emoji":"💛","prompt":"Tell a grown-up about a time someone helped you feel included.","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"loaves","title":"A shared meal","category":"faith","emoji":"🍞","reference":"John 6:1–13","lesson":"Sharing and noticing needs are ways to care.","scenes":[{"title":"A hungry crowd","text":"A large crowd had been listening to Jesus. It was time to eat, but there was very little food nearby.","emoji":"👪","prompt":"How can we notice what other people need?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"Five and two","text":"A boy had five barley loaves and two fish. Jesus gave thanks, and the food was shared with the crowd.","emoji":"🍞","prompt":"Five loaves and two fish: how many items?","choices":[{"label":"Seven","response":"Five plus two makes seven."},{"label":"Six","response":"Count five, then one more is six, and one more is seven."}]},{"title":"Enough to share","text":"Everyone ate, and the helpers gathered what was left. Christians remember this as a story of Jesus’ care and generosity.","emoji":"🧺","prompt":"What is something you can share besides food?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"easter","title":"A morning of hope","category":"faith","emoji":"🌅","reference":"Luke 24:1–12","lesson":"Christians celebrate Easter as a story of hope and new life.","prayer":"Dear God, thank you for hope and love. Be close to people who are sad. Amen.","scenes":[{"title":"A sad time","text":"Jesus’ friends were very sad after he died. They cared for one another. When we are sad, it helps to be with someone we trust.","emoji":"💜","prompt":"Who is a trusted grown-up you can talk to when you feel sad?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]},{"title":"An early visit","text":"Early in the morning, women went to the tomb. They found the stone moved away and heard the message that Jesus had risen.","emoji":"🌅","prompt":"What happened first?","choices":[{"label":"The women went to the tomb","response":"They went early in the morning, then discovered the stone was moved."},{"label":"They shared the news","response":"They shared the news after their visit."}]},{"title":"Sharing hope","text":"The women shared the news with Jesus’ friends. Christians celebrate his resurrection at Easter. Families can talk together about what this story means.","emoji":"🌷","prompt":"What brings your family hope?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"crayons","title":"The great crayon tumble","category":"character","emoji":"🖍️","lesson":"Kindness starts with noticing.","scenes":[{"title":"A colorful clatter","text":"Mira’s crayons rolled all over the floor. She looked at the mess and sighed. Pip was ready to go outside.","emoji":"🖍️","prompt":"What could Pip do?","choices":[{"label":"Help pick them up","response":"Pip kneels down. The two friends gather the crayons together."},{"label":"Ask if Mira wants help","response":"Mira says yes. Asking gives her a choice and shows care."}]},{"title":"One is broken","text":"Pip sees a broken blue crayon. He accidentally stepped on it.","emoji":"💙","prompt":"What could Pip say?","choices":[{"label":"I stepped on it. I’m sorry.","response":"Being honest helps Mira understand. They can still draw with the two pieces."},{"label":"Maybe hide it","response":"Hiding it might leave Mira confused. Pip can be brave and tell the truth."}]},{"title":"A picture together","text":"Mira draws the sky with one blue piece. Pip uses the other to draw a pond. A mistake became a chance to help and repair.","emoji":"🎨","prompt":"What could you do after making a mistake?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"bridge-friends","title":"Two ideas, one bridge","category":"character","emoji":"🌉","lesson":"Listening and taking turns help us solve problems.","scenes":[{"title":"Two plans","text":"Byte wants a tall bridge. Tiko wants a wide bridge. They both reach for the same blocks.","emoji":"🧱","prompt":"How could they begin?","choices":[{"label":"Take turns explaining","response":"Each builder gets time to show an idea."},{"label":"Test both plans","response":"They agree on a small test before choosing."}]},{"title":"The tower wobbles","text":"Their first bridge wobbles. Byte feels frustrated. Tiko remembers that builders learn by testing.","emoji":"🏗️","prompt":"What could help?","choices":[{"label":"Pause and breathe","response":"A short pause makes room for the next idea."},{"label":"Try a wider base","response":"They change one thing and test again."}]},{"title":"A shared crossing","text":"The friends combine their ideas. They celebrate helping each other, not whose idea was best.","emoji":"🤝","prompt":"How could you thank someone who helped you today?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]},{"id":"seed-story","title":"The patient little seed","category":"science","emoji":"🌱","lesson":"Observing change takes patience.","scenes":[{"title":"A tiny beginning","text":"Pip puts a bean seed in a pot. He wonders what it needs. He gives it water, air, and a suitable warm place.","emoji":"🫘","prompt":"What could Pip record?","choices":[{"label":"A drawing each day","response":"Drawings let us compare changes over time."},{"label":"How much water he gives","response":"Keeping a record can help him explain what happened."}]},{"title":"Look closely","text":"After a while, a root appears, then a shoot. Once leaves grow, the plant needs light to make food.","emoji":"🌱","prompt":"Why might we compare two pots carefully?","choices":[{"label":"To test one change","response":"Changing one thing makes the comparison easier to understand."},{"label":"To see which child is better","response":"Plants grow differently. A plant experiment is about evidence, not ranking people."}]},{"title":"A new question","text":"The plant keeps changing. Pip asks: What would happen if we turned the pot? A good observation can lead to another question.","emoji":"🌿","prompt":"What would you like to observe tomorrow?","choices":[{"label":"Tell a grown-up","response":"Take a moment to share your idea."},{"label":"Think quietly","response":"Your thoughts are welcome. Take your time."}]}]}],"prayers":[{"id":"morning","title":"Morning","emoji":"☀️","lines":["Dear God, thank you for this new day.","Help me learn, listen, and be kind.","Be with our family today. Amen."]},{"id":"bedtime","title":"Bedtime","emoji":"🌙","lines":["Dear God, thank you for today.","Help my body and mind rest.","Hold our family in your love. Amen."]},{"id":"thanks","title":"Thank you","emoji":"🌷","lines":["Dear God, thank you for the good things around me.","Thank you for people who care for me.","Help me notice one little blessing today. Amen."]},{"id":"family","title":"Our family","emoji":"🏡","lines":["Dear God, be close to our family.","Help us listen, share, and forgive.","Help us care for one another. Amen."]},{"id":"meal","title":"Before a meal","emoji":"🍎","lines":["Dear God, thank you for this food.","Thank you for the people who helped it reach our table.","Help us care for people who need food. Amen."]},{"id":"afraid","title":"When I feel afraid","emoji":"🕯️","lines":["Dear God, I feel afraid.","Help me talk with a grown-up I trust.","Help me feel your love and take one calm breath. Amen."]},{"id":"sick","title":"Someone is sick","emoji":"💛","lines":["Dear God, please be near someone who is sick.","Thank you for the people caring for them.","Help us show kindness and find good help. Amen."]},{"id":"forgive","title":"Making things right","emoji":"🤲","lines":["Dear God, I made a mistake.","Help me tell the truth and say I am sorry.","Help me repair what I can and try again. Amen."]},{"id":"school","title":"Learning and friends","emoji":"📚","lines":["Dear God, thank you for chances to learn.","Help me ask questions and welcome others.","Bless our teachers and friends. Amen."]}]}'::jsonb) on conflict(name) do update set data=excluded.data,version=catalogs.version+1;
