insert into public.activities(id,lesson_id,slug,engine_kind,config,published) values('cff4d6b3-46cf-a4e2-724a-18dcc3b215e8','436e2967-a41f-e93e-7598-1253df7fe56c','prek-reading-0','sound-choice','{"id":"prek-reading-0","grade":"prek","subject":"reading","level":1,"skillId":"LIT.PK.PA.INITIAL_01","activityType":"sound-choice","phase":"guided","estimatedMinutes":2,"contextTags":["nature"],"prompt":"Which letter starts the word “sun”?","options":["s","m","t"],"hint":"Say “sun” slowly. Listen to the first sound.","visual":"sun"}'::jsonb,true) on conflict(id) do update set engine_kind=excluded.engine_kind,config=excluded.config,published=excluded.published;
