insert into public.media_assets(id,slug,title,media_type,metadata,published) values('58c8c41b-a445-443d-9ba4-9ed48543caf5','missing-map','Nova and the Missing Map','scene','{"id":"missing-map","title":"Nova and the Missing Map","category":"CurioQuest Cartoons","domain":"reading","skills":["sound_m","sound_a","sound_p","blend_cvc"],"ageMin":3,"ageMax":8,"duration":240,"active":true,"videoUrl":null,"captionUrl":null,"thumbnail":"map","scenes":[{"id":"forest","caption":"A treasure garden is waiting! Nova packed a snack and a compass. But where is the map?","setting":"forest","duration":7,"nova":"wave"},{"id":"glow","caption":"A little light flickers near a tree. The first sound in moon will help us find its letter.","setting":"letters","duration":7,"nova":"point","letters":"m"},{"id":"sounds","caption":"Three letters are glowing. Touch m, then a, then p. Say each sound with your grown-up.","setting":"letters","duration":7,"nova":"listen","letters":"m a p"},{"id":"bridge","caption":"Bring the sounds together. Keep the first two sounds going, then finish with a tiny p.","setting":"letters","duration":7,"nova":"explain","letters":"m a p"},{"id":"word","caption":"The sounds make a word! Read it first. Then we can discover what it means.","setting":"letters","duration":6,"nova":"encourage","letters":"map"},{"id":"route","caption":"A map shows a route. Which word did we read? Look at every letter.","setting":"forest","duration":7,"nova":"listen"},{"id":"garden","caption":"You helped Nova reach the treasure garden! Your Explorer Map belongs in your treehouse.","setting":"garden","duration":7,"nova":"celebrate"}]}'::jsonb,true) on conflict(id) do update set metadata=excluded.metadata;
